const BALPAKRAM_DATA={id:"balpakram",name:"Balpakram National Park",location:"South Garo Hills District, Meghalaya",established:1987,totalArea:"220 km²",altitude:"300m – 910m",coordinates:{lat:25.25,lng:90.87},quickStats:[{label:"Total Area",value:"220 km²",icon:"🏞️"},{label:"Established",value:"1987",icon:"📜"},{label:"Altitude Range",value:"300m–910m",icon:"⛰️"},{label:"Bird Species",value:"300+",icon:"🦅"}],history:{title:"History & Establishment",description:"Notified as a protected reserve in the mid-1980s and formally declared a National Park in 1987, Balpakram sits in the remote South Garo Hills close to the Indo-Bangladesh border. Its western boundary adjoins the Siju Bird Sanctuary along the banks of the Simsang River, together forming one of Meghalaya's most significant conservation corridors.",facts:["Declared a National Park in 1987 at an altitude of nearly 3,000 ft.","Adjoins Siju Bird Sanctuary along the Simsang River to the west.","Administered from the DFO office in Baghmara, the South Garo Hills headquarters.","Remains largely undeveloped, preserving one of India's richest biodiversity pockets."]},mythology:{title:"Land of Perpetual Winds: Myths & Legends",description:'In Garo mythology, "Balpakram" translates to the land of the perpetual wind. The Garo tribe regards the plateau as the resting place of departed souls, and generations of folklore have layered the park with spirits, guardians, and sacred landmarks.',legends:[{name:"Resting Place of Souls",icon:"🌬️",status:"Garo Belief",desc:"The Garo people believe Balpakram is where the spirits of the dead journey after leaving the mortal world, making the plateau one of the community's most sacred sites."},{name:"The Mandeburung",icon:"👣",status:"Folklore Spirit",desc:'Local folklore speaks of the "mandeburung", a legendary jungle spirit said to roam the deep forests, echoing tales of the yeti or bigfoot across cultures.'},{name:"Boldak Matchu Karam",icon:"🦶",status:"Sacred Landmark",desc:"A rock formation believed by the Garo to be a fossilised human footprint, regarded as a mark left by ancestral spirits upon the land."},{name:"Chidimak Lake",icon:"🌊",status:"Sacred Site",desc:"A small sacred lake within the park held in reverence by the Garo community, tied to local ritual and spiritual significance."},{name:"Wangala Festival Connection",icon:"🥁",status:"Living Tradition",desc:"The Garo's annual Wangala harvest festival, honouring the spirits believed to inhabit Balpakram, is celebrated with traditional drums, dance, and rituals."}]},landscape:{title:"Plateau, Gorges & Geology",description:"Balpakram's terrain shifts dramatically from sunlit table-top plateaus to shadowy gorges and limestone caves, earning it comparisons to the Grand Canyon. Windswept cliffs tower over the Simsang River valley, framing some of Meghalaya's most striking panoramas.",features:[{name:"Balpakram Plateau & Gorge",icon:"🏜️",status:"Signature Landform",desc:"A dramatic tableland cut by a deep forested canyon, often compared to the Grand Canyon for its scale and rugged beauty."},{name:"Limestone Caves & Rock Formations",icon:"🕳️",status:"Geological Feature",desc:"Numerous caves and karst formations dot the park, including passages linked to the wider Siju cave system nearby."},{name:"Simsang River Valley",icon:"🏞️",status:"Scenic Viewpoint",desc:"Steep cliffs overlook the winding Simsang River valley, one of the most photographed viewpoints in the park."},{name:"Elevation Gradient",icon:"⛰️",status:"300m – 910m",desc:"Terrain rises from lowland river valleys to high plateaus, creating a transition of subtropical, grassland, and bamboo forest zones."}]},wildlife:[{name:"Red Panda (Ailurus fulgens)",status:"Endangered",icon:"🐼",desc:"One of the world's most elusive small mammals, found in Balpakram's higher forested elevations alongside its stronghold at neighbouring Nokrek."},{name:"Bengal Tiger (Panthera tigris)",status:"Flagship Predator",icon:"🐅",desc:"Along with the Asian elephant, the tiger is one of Balpakram's flagship species, roaming its dense forests and grasslands."},{name:"Asian Elephant (Elephas maximus)",status:"Flagship Species",icon:"🐘",desc:"Herds move seasonally through the park's forests and valleys, particularly visible during the winter months."},{name:"Clouded Leopard (Neofelis nebulosa)",status:"Vulnerable",icon:"🐆",desc:"An elusive, arboreal wild cat recorded through camera-trap surveys across Balpakram's dense canopy."},{name:"Hoolock Gibbon (Hoolock hoolock)",status:"India's Only Ape",icon:"🐒",desc:"The only ape species native to India, swinging through Balpakram's treetops and calling at dawn across the forest."},{name:"Wild Water Buffalo",status:"Endangered",icon:"🐃",desc:"One of the rarest large mammals in the park, found along river valleys and grassland edges."},{name:"Marbled Cat & Asian Golden Cat",status:"Rare Felids",icon:"🐈",desc:"Two secretive small wild cats recorded in camera-trap surveys, reflecting the park's status as a felid biodiversity hotspot."},{name:"Great Indian Hornbill",status:"Avian Icon",icon:"🦅",desc:"Balpakram supports over 300 bird species, with the Great Hornbill among its most striking residents."}],flora:[{name:"Pitcher Plant (Nepenthes khasiana)",status:"India's Only Nepenthes",icon:"🪴",desc:"An insectivorous rarity endemic to the Garo, Khasi, and Jaintia Hills, and the only native pitcher plant species found in India."},{name:"Sundew (Drosera spp.)",status:"Carnivorous Plant",icon:"🌿",desc:"Delicate carnivorous plants that trap insects on sticky, dew-covered leaves, thriving in the park's damp grassland patches."},{name:"Wild Orchids",status:"Endemic Diversity",icon:"🌸",desc:"A rich variety of epiphytic and terrestrial orchids flourish across Balpakram's subtropical and evergreen forest zones."},{name:"Medicinal Herbs",status:"Traditional Use",icon:"🍃",desc:"Numerous herbs used in traditional Garo medicine grow wild across the park's grasslands and forest understorey."}],waterfalls:{title:"Rivers & Waterfalls",description:"The Simsang and Mahadeo rivers cut through Balpakram, feeding cascades such as Rongdong Falls that are at their most spectacular during the monsoon season, when the plateau's cliffs come alive with rushing water.",highlights:["Rongdong Falls — a scenic monsoon-season cascade fed by the Simsang River.","Simsang River — the region's lifeline, forming deep valleys and multiple smaller falls.","Mahadeo River — a tributary adding to the park's network of waterfalls and streams.","Best viewed June–September, when monsoon rains are at their peak."]},mapHotspots:[{id:"gate",name:"Baghmara Entrance & DFO Office",x:150,y:480,desc:"Permit checkpoint and starting point for most visits, located in the South Garo Hills headquarters town."},{id:"plateau",name:"Balpakram Plateau Viewpoint",x:460,y:180,desc:"Table-top plateau offering panoramic views often compared to the Grand Canyon."},{id:"gorge",name:"Simsang River Gorge",x:650,y:320,desc:"Dramatic cliffside overlook of the winding Simsang River valley below."},{id:"lake",name:"Chidimak Lake",x:320,y:380,desc:"A small sacred lake revered by the Garo community, tied to local mythology."},{id:"falls",name:"Rongdong Falls",x:780,y:460,desc:"Monsoon-season waterfall cascading from the Simsang River, a highlight for seasonal visitors."}],gallery:[{emoji:"🐼",title:"Red Panda",caption:"Red Panda resting in Balpakram's dense subtropical forest canopy."},{emoji:"🐆",title:"Clouded Leopard",caption:"Clouded Leopard, one of Balpakram's most elusive resident wild cats."},{emoji:"🐒",title:"Hoolock Gibbon",caption:"Hoolock Gibbon, India's only ape species, swinging through the Garo Hills canopy."},{emoji:"🪴",title:"Pitcher Plant",caption:"Nepenthes khasiana, India's only native pitcher plant, endemic to the Garo Hills region."},{emoji:"🏜️",title:"Balpakram Plateau",caption:"The table-top plateau and gorge, often compared to the Grand Canyon of the Garo Hills."},{emoji:"💦",title:"Rongdong Falls",caption:"Rongdong Falls cascading from the Simsang River during the monsoon season."}]};"undefined"!=typeof module&&(module.exports={BALPAKRAM_DATA:BALPAKRAM_DATA});